mod access_key_db{
 static EPOCH:core::sync::atomic::AtomicU64=core::sync::atomic::AtomicU64::new(1);
 pub fn principal_epoch(_:u8)->Option<u64>{Some(EPOCH.load(core::sync::atomic::Ordering::SeqCst))}
 pub fn authorize_record_at(vm:u8,epoch:u64,key:trueos_fs::RecordKey)->Result<(),()>{if Some(epoch)!=principal_epoch(vm){Err(())}else{authorize_record(vm,key)}}
 pub fn workspace_for_vm_at(vm:u8,epoch:u64)->Option<String>{if Some(epoch)==principal_epoch(vm){workspace_for_vm(vm)}else{None}}
 pub fn authorize_protected_workspace_at(vm:u8,epoch:u64,key:trueos_fs::RecordKey)->Result<(),()>{if Some(epoch)!=principal_epoch(vm){Err(())}else{authorize_protected_workspace(vm,key)}}
 pub fn reset_epoch(){EPOCH.store(1,core::sync::atomic::Ordering::SeqCst);}
 pub fn reuse_slot(){EPOCH.fetch_add(1,core::sync::atomic::Ordering::SeqCst);}
 static GRANTS:spin::Mutex<std::collections::BTreeMap<u8,Vec<trueos_fs::RecordKey>>>=spin::Mutex::new(std::collections::BTreeMap::new());
 pub fn authorize_record(vm:u8,key:trueos_fs::RecordKey)->Result<(),()>{if key==trueos_fs::RecordKey::Ffa||GRANTS.lock().get(&vm).is_some_and(|keys|keys.contains(&key)){Ok(())}else{Err(())}}
 pub fn grant(vm:u8,key:trueos_fs::RecordKey){GRANTS.lock().entry(vm).or_default().push(key);}
 pub fn workspace_for_vm(vm:u8)->Option<String>{(vm==1).then(||"apps/demo".into())}
 pub fn authorize_protected_workspace(vm:u8,key:trueos_fs::RecordKey)->Result<(),()>{if vm==1{authorize_record(vm,key)}else{Err(())}}
 pub fn clear(){GRANTS.lock().clear();}
}
