   use alloc::{collections::BTreeMap,string::String,vec::Vec};use crate::disc::block;use spin::Mutex;use core::sync::atomic::{AtomicU32,Ordering};
   const TRUEOSFS_LIST_SOFT_CAP:usize=1024;
   static FILE_WRITE_STREAM_SEQ:AtomicU32=AtomicU32::new(1);
   static FILE_WRITE_STREAMS:Mutex<BTreeMap<u32,FileWriteStream>>=Mutex::new(BTreeMap::new());
   pub use trueos_fs::{ContentTypeId,RecordKey,NodeKind,NodeInfo,DirEntry};
   #[derive(Debug)]struct DirListing{entries:Vec<DirEntry>,truncated:bool}
   #[derive(Debug)]struct IndexNode{path:String,kind:NodeKind}
   enum ContentIdentityRejectReason{TypeRequired,UnregisteredType,LegacyDowngrade}
   fn record_type_reject(_:ContentIdentityRejectReason){}
   struct RootMount{disk_id:block::DiscId,seq:u32,index:Option<Box<BTreeMap<Vec<u8>,IndexRef>>>}
   static ROOTS:Mutex<Vec<RootMount>>=Mutex::new(Vec::new());
   static INDEX:Mutex<BTreeMap<String,trueos_fs::NodeRecordRef>>=Mutex::new(BTreeMap::new());
   static DISK:Mutex<Vec<u8>>=Mutex::new(Vec::new());
   static READ_CALLS:core::sync::atomic::AtomicUsize=core::sync::atomic::AtomicUsize::new(0);
   static FAIL_WRITE:core::sync::atomic::AtomicBool=core::sync::atomic::AtomicBool::new(false);
   static WRITER:core::sync::atomic::AtomicBool=core::sync::atomic::AtomicBool::new(false);
   std::thread_local!{static THIS_WRITER:core::cell::Cell<bool>=const{core::cell::Cell::new(false)};}
   #[derive(Clone,Copy)]struct Placement{super_lba:u64,data_lba:u64,data_end_lba_exclusive:Option<u64>}
   struct KernelBlockIo;impl KernelBlockIo{fn new(_:block::DeviceHandle)->Self{Self}}
   impl trueos_fs::BlockIo for KernelBlockIo{
    type Error=block::Error;fn block_size(&self)->usize{512}fn block_count(&self)->u64{32768}
    async fn read_blocks(&self,lba:u64,blocks:usize)->Result<Vec<u8>,Self::Error>{READ_CALLS.fetch_add(1,core::sync::atomic::Ordering::SeqCst);let bytes=DISK.lock();let start=lba as usize*512;Ok(bytes.get(start..start+blocks*512).ok_or(block::Error::OutOfBounds)?.to_vec())}
    async fn write_blocks(&self,lba:u64,bytes:&[u8])->Result<(),Self::Error>{assert!(WRITER.load(core::sync::atomic::Ordering::SeqCst));if FAIL_WRITE.swap(false,core::sync::atomic::Ordering::SeqCst){return Err(block::Error::Io)}let mut data=DISK.lock();let start=lba as usize*512;data.get_mut(start..start+bytes.len()).ok_or(block::Error::OutOfBounds)?.copy_from_slice(bytes);Ok(())}
    async fn flush(&self)->Result<(),Self::Error>{Ok(())}
   }
   fn map_engine_err(error:trueos_fs::FsError<block::Error>)->block::Error{match error{trueos_fs::FsError::Device(e)=>e,trueos_fs::FsError::InvalidParam=>block::Error::InvalidParam,_=>block::Error::Corrupted}}
   async fn placement_for_io_async(_:block::DeviceHandle)->Result<Option<Placement>,block::Error>{Ok(Some(Placement{super_lba:0,data_lba:1,data_end_lba_exclusive:Some(32768)}))}
   async fn ensure_index_async(_:block::DeviceHandle,_:&Placement)->Result<(),block::Error>{assert!(!THIS_WRITER.get(),"index construction cannot recursively hold its own root lease");Ok(())}
   mod write_gate{use super::*;pub struct RootWriteLease;impl RootWriteLease{pub async fn acquire(_:block::DiscId)->Self{core::future::poll_fn(|cx|if WRITER.compare_exchange(false,true,core::sync::atomic::Ordering::SeqCst,core::sync::atomic::Ordering::SeqCst).is_ok(){THIS_WRITER.set(true);core::task::Poll::Ready(Self)}else{cx.waker().wake_by_ref();core::task::Poll::Pending}).await}}impl Drop for RootWriteLease{fn drop(&mut self){THIS_WRITER.set(false);WRITER.store(false,core::sync::atomic::Ordering::SeqCst);}}}
   #[derive(Clone,Copy,Debug)]struct IndexRef{entry_lba:u64,kind:trueos_fs::LogKind,content_type:ContentTypeId}
   fn refresh_index(){let snapshot=INDEX.lock().iter().map(|(path,node)|(path.as_bytes().to_vec(),IndexRef{entry_lba:node.entry_lba,kind:if node.kind==NodeKind::Directory{trueos_fs::LogKind::Directory}else{trueos_fs::LogKind::Put},content_type:node.content_type})).collect();ROOTS.lock()[0].index=Some(Box::new(snapshot));}
   fn indexed_removal_entry(_:block::DiscId,path:&str)->Result<Option<IndexRef>,block::Error>{assert!(THIS_WRITER.get(),"record lookup must hold this caller root lease");Ok(INDEX.lock().get(path).map(|r|IndexRef{entry_lba:r.entry_lba,kind:if r.kind==NodeKind::Directory{trueos_fs::LogKind::Directory}else{trueos_fs::LogKind::Put},content_type:r.content_type}))}
   fn validate_indexed_file_target(_:block::DiscId,path:&str,_:bool)->Result<bool,block::Error>{assert!(WRITER.load(core::sync::atomic::Ordering::SeqCst));if let Some((parent,_))=path.rsplit_once('/'){if INDEX.lock().get(parent).is_none_or(|node|node.kind!=NodeKind::Directory){return Err(block::Error::InvalidParam)}}Ok(true)}
   fn record_successful_content_commit(_:ContentTypeId,_:bool){}fn bump_root_cache_gen(_:block::DiscId){}fn file_record_cache_invalidate_path(_:block::DiscId,_:&str){}fn file_record_cache_insert(_:block::DiscId,_:&str,_:trueos_fs::FileRecordRef){}fn update_root_index_put(_:block::DiscId,path:&str,record:trueos_fs::FileRecordRef)->bool{INDEX.lock().insert(path.into(),record.into());refresh_index();true}fn invalidate_root_index(_:block::DiscId){}
   fn update_root_index_node(_:block::DiscId,path:&str,record:trueos_fs::NodeRecordRef)->bool{INDEX.lock().insert(path.into(),record);refresh_index();true}
   fn validate_indexed_directory_target(_:block::DiscId,path:&str)->Result<bool,CreateDirectoryError>{let index=INDEX.lock();if index.contains_key(path){return Err(CreateDirectoryError::AlreadyExists)}if let Some((parent,_))=path.rsplit_once('/') {match index.get(parent){None=>return Err(CreateDirectoryError::MissingParent),Some(n)if n.kind!=NodeKind::Directory=>return Err(CreateDirectoryError::ParentNotDirectory),_=>{}}}Ok(true)}
   fn file_record_cache_invalidate_prefix(_:block::DiscId,_:&str){}
   fn update_root_index_delete(_:block::DiscId,path:&str)->bool{INDEX.lock().remove(path);refresh_index();true}
   fn update_root_index_delete_tree(_:block::DiscId,path:&str)->bool{let prefix=format!("{path}/");INDEX.lock().retain(|name,_|name!=path&&!name.starts_with(&prefix));refresh_index();true}
   fn update_root_index_rename_tree(_:block::DiscId,moves:&[(String,String,IndexRef)])->bool{let changes:Vec<_>={let mut index=INDEX.lock();moves.iter().map(|(src,dst,_)|(dst.clone(),index.remove(src).unwrap())).collect()};for(dst,node)in changes{INDEX.lock().insert(dst,node);}refresh_index();true}
