    #[test]fn conditional_and_streamed_writes_authorize_at_publication(){
     reset();use authorized::{self as auth,Actor};use sha2::{Digest,Sha256};crate::run(auth::create_dir_all(Actor::Host,D,"apps/demo")).unwrap();crate::run(stamp_directory_key_async(D,"apps/demo",key(8))).unwrap();crate::access_key_db::grant(1,key(8));assert_eq!(crate::run(auth::write_checked(Actor::Vm(1,1),D,"apps/demo/state",b"old",ContentTypeId::BLOB,true,None,false,false)),Ok(true));let file_id=INDEX.lock()["apps/demo/state"].file_id;let expected: [u8;32]=Sha256::digest(b"old").into();assert_eq!(crate::run(auth::write_checked(Actor::Vm(2,1),D,"apps/demo/state",b"bad",ContentTypeId::BLOB,false,Some(expected),false,false)),Err(CheckedWriteError::Device(block::Error::PermissionDenied)));assert_eq!(crate::run(auth::write_checked(Actor::Vm(1,1),D,"apps/demo/state",b"new",ContentTypeId::BLOB,false,Some(expected),false,false)),Ok(true));assert_eq!(INDEX.lock()["apps/demo/state"].file_id,file_id);assert_eq!(crate::run(auth::write_checked(Actor::Vm(1,1),D,"apps/demo/state",b"bad",ContentTypeId::BLOB,false,Some(expected),false,false)),Err(CheckedWriteError::Conflict));let handle=crate::run(auth::write_begin(Actor::Vm(1,1),D,"apps/demo/state",6,ContentTypeId::BLOB,true)).unwrap().unwrap();crate::run(file_write_chunk_async(handle,b"first")).unwrap();crate::access_key_db::clear();assert_eq!(crate::run(file_write_finish_async(handle)),Err(block::Error::PermissionDenied));assert!(!WRITER.load(Ordering::SeqCst));assert_eq!(disk("apps/demo/state").unwrap(),b"new");crate::access_key_db::grant(1,key(8));let handle=crate::run(auth::write_begin(Actor::Vm(1,1),D,"apps/demo/state",3,ContentTypeId::BLOB,true)).unwrap().unwrap();crate::run(file_write_chunk_async(handle,b"yes")).unwrap();crate::run(file_write_finish_async(handle)).unwrap();assert_eq!(disk("apps/demo/state").unwrap(),b"yes");assert_eq!(INDEX.lock()["apps/demo/state"].file_id,file_id);
    }
