     reset();use authorized::{self as auth,Actor};crate::run(auth::create_dir_all(Actor::Host,D,"apps/demo")).unwrap();crate::run(stamp_directory_key_async(D,"apps/demo",key(9))).unwrap();crate::access_key_db::grant(1,key(9));crate::run(auth::write(Actor::Vm(1,1),D,"apps/demo/text",b"private",ContentTypeId::UTF8_TEXT,false)).unwrap();crate::run(auth::write(Actor::Public,D,"public",b"open",ContentTypeId::UTF8_TEXT,false)).unwrap();assert!(matches!(crate::run(auth::open_read(Actor::Public,D,"apps/demo/text")),Err(block::Error::PermissionDenied)));let handle=crate::run(auth::open_read(Actor::Vm(1,1),D,"apps/demo/text")).unwrap().unwrap();crate::run(auth::write(Actor::Vm(1,1),D,"apps/demo/text",b"changed",ContentTypeId::UTF8_TEXT,false)).unwrap();let mut bytes=[0;8];assert_eq!(crate::run(file_read_handle_range_async(handle,0,&mut bytes)),Ok(Some(7)));assert_eq!(&bytes[..7],b"private");crate::access_key_db::reuse_slot();assert_eq!(crate::run(file_read_handle_range_async(handle,0,&mut bytes)),Err(block::Error::PermissionDenied));crate::access_key_db::reset_epoch();assert_eq!(crate::run(auth::select(Actor::Public,D,"",ContentTypeId::UTF8_TEXT,8)).unwrap().files,vec![String::from("public")]);assert_eq!(crate::run(auth::select(Actor::Vm(1,1),D,"apps/demo",ContentTypeId::UTF8_TEXT,8)).unwrap().files,vec![String::from("text")]);let public=crate::run(auth::json_all(Actor::Public,D,100)).unwrap().unwrap();assert!(public.contains("public"));assert!(!public.contains("demo"));let owner=crate::run(auth::json_all(Actor::Vm(1,1),D,100)).unwrap().unwrap();assert!(owner.contains("apps/demo/text"));assert!(owner.contains("\"kind\":\"key\""));
